-- DW4Online migration 0009: the achievement catalogue adopts the game client's (docs/SEAMLESS.md 11). The client's 72 ids,
-- titles, descriptions, categories and thresholds are the catalogue (src/game/achievements.cpp, exported as
-- data/online/achievements.json; DW4Online.Tests and the client's ctest compare this file with it). 52 codes of 0002 keep
-- their ids and take the client's text, kind, goal and counter; the client's 20 others are new (ids 73-92); the 20 codes of
-- 0002 the client does not have are retired (active = 0, never reused). Tier, points and hidden stay the server's.
-- kind: event = reported by the game when it happens; stat = the server unlocks it when player_stats.<stat_key> reaches
-- goal; state = the server unlocks it from its own decode of an online character upload. Goals of event kinds are limits
-- the server checks: speed_* seconds of in-game time (8 h and 4 h), lowlevel_apocalymon the highest level (12).

ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), category = VALUES(category),
  kind = VALUES(kind), goal = VALUES(goal), stat_key = VALUES(stat_key), sort_order = VALUES(sort_order), active = 1;

-- The codes of 0002 the client does not have.
UPDATE achievements SET active = 0 WHERE code IN (
  'story_briefing', 'story_gate_keys', 'story_leomon', 'boss_apocalymon', 'story_restore',
  'story_plugs', 'boss_belphemon', 'story_maze', 'boss_lucemon', 'boss_lordknightmon',
  'boss_daemon', 'lowlevel_daemon', 'speed_6h', 'speed_3h', 'quest_vh',
  'form_mega', 'form_all16', 'weapon_virtuoso', 'capsule_recover', 'online_ten');
